/*! bxSlider lightweight build for project needs (API-compatible subset). */
(function ($) {
    'use strict';

    var defaults = {
        slideSelector: '',
        infiniteLoop: true,
        speed: 500,
        slideMargin: 0,
        slideWidth: 0,
        startSlide: 0,
        minSlides: 1,
        maxSlides: 1,
        moveSlides: 1,
        responsive: true,
        pager: false,
        controls: false,
        onSliderLoad: function () {},
        onSlideBefore: function () {},
        onSlideAfter: function () {},
        onSlideNext: function () {},
        onSlidePrev: function () {},
        onSliderResize: function () {}
    };

    function ensureWrapped($el) {
        if ($el.parent().hasClass('bx-viewport') && $el.parent().parent().hasClass('bx-wrapper')) {
            return {
                $viewport: $el.parent(),
                $wrapper: $el.parent().parent()
            };
        }

        $el.wrap('<div class="bx-wrapper"><div class="bx-viewport"></div></div>');
        return {
            $viewport: $el.parent(),
            $wrapper: $el.parent().parent()
        };
    }

    $.fn.bxSlider = function (options) {
        if (!this.length) {
            return this;
        }

        if (this.length > 1) {
            return this.each(function () {
                $(this).bxSlider(options);
            });
        }

        var settings = $.extend({}, defaults, options);
        var $slider = this;
        var wrapped = ensureWrapped($slider);
        var $viewport = wrapped.$viewport;
        var $wrapper = wrapped.$wrapper;
        var $slides = $slider.children(settings.slideSelector);

        var state = {
            index: Math.max(0, parseInt(settings.startSlide, 10) || 0),
            visible: 1,
            slidePixelWidth: 0,
            pages: 1,
            destroyed: false
        };

        // Зберігаємо оригінальні стилі, щоби безпечно відкотити destroySlider().
        if (typeof $slider.data('bx-orig-style') === 'undefined') {
            $slider.data('bx-orig-style', $slider.attr('style') || null);
            $slides.each(function () {
                var $slide = $(this);
                $slide.data('bx-orig-style', $slide.attr('style') || null);
            });
        }

        function getVisibleSlides() {
            var viewportWidth = $viewport.width();
            var minSlides = Math.max(1, parseInt(settings.minSlides, 10) || 1);
            var maxSlides = Math.max(minSlides, parseInt(settings.maxSlides, 10) || minSlides);
            var baseWidth = parseInt(settings.slideWidth, 10) || 0;

            if (!baseWidth) {
                return Math.min(maxSlides, $slides.length || 1);
            }

            // Обчислюємо кількість видимих слайдів у межах [minSlides, maxSlides].
            var fit = Math.floor((viewportWidth + settings.slideMargin) / (baseWidth + settings.slideMargin));
            fit = Math.max(minSlides, Math.min(maxSlides, fit));
            return Math.min(fit, $slides.length || 1);
        }

        function computePageCount(visible) {
            var total = $slides.length;
            if (total <= visible) {
                return 1;
            }
            var step = Math.max(1, Math.min(parseInt(settings.moveSlides, 10) || 1, visible));
            return Math.ceil((total - visible) / step) + 1;
        }

        function applyLayout() {
            var viewportWidth = $viewport.width();
            state.visible = getVisibleSlides();
            var margin = parseInt(settings.slideMargin, 10) || 0;
            state.slidePixelWidth = Math.floor((viewportWidth - margin * (state.visible - 1)) / state.visible);

            $viewport.css({
                width: '100%',
                overflow: 'hidden',
                position: 'relative'
            });

            $slider.css({
                position: 'relative',
                width: ($slides.length * (state.slidePixelWidth + margin)) + 'px',
                margin: 0,
                padding: 0,
                listStyle: 'none',
                transform: 'translate3d(0,0,0)',
                transition: 'transform ' + settings.speed + 'ms ease'
            });

            $slides.css({
                float: 'left',
                width: state.slidePixelWidth + 'px',
                marginRight: margin + 'px',
                listStyle: 'none'
            });

            state.pages = computePageCount(state.visible);
            if (state.index >= state.pages) {
                state.index = state.pages - 1;
            }

            goToPage(state.index, false);
        }

        function getOffsetForPage(pageIndex) {
            var step = Math.max(1, Math.min(parseInt(settings.moveSlides, 10) || 1, state.visible));
            var slidePosition = pageIndex * step;
            var maxStart = Math.max(0, $slides.length - state.visible);
            slidePosition = Math.min(slidePosition, maxStart);
            return slidePosition * (state.slidePixelWidth + (parseInt(settings.slideMargin, 10) || 0));
        }

        function goToPage(pageIndex, animated, direction) {
            if (state.destroyed) {
                return;
            }

            var oldIndex = state.index;
            var target = pageIndex;

            if (settings.infiniteLoop) {
                if (target < 0) {
                    target = state.pages - 1;
                }
                if (target >= state.pages) {
                    target = 0;
                }
            } else {
                target = Math.max(0, Math.min(state.pages - 1, target));
            }

            if (target === oldIndex && animated !== false) {
                return;
            }

            state.index = target;
            settings.onSlideBefore($slides.eq(target), oldIndex, target);
            if (direction === 'next') {
                settings.onSlideNext($slides.eq(target), oldIndex, target);
            } else if (direction === 'prev') {
                settings.onSlidePrev($slides.eq(target), oldIndex, target);
            }

            $slider.css('transition', animated === false ? 'none' : ('transform ' + settings.speed + 'ms ease'));
            $slider.css('transform', 'translate3d(' + (-getOffsetForPage(target)) + 'px,0,0)');

            window.setTimeout(function () {
                settings.onSlideAfter($slides.eq(target), oldIndex, target);
            }, animated === false ? 0 : settings.speed);
        }

        function handleResize() {
            if (state.destroyed || !settings.responsive) {
                return;
            }
            applyLayout();
            settings.onSliderResize.call($slider, state.index);
        }

        function restoreOriginalStyles() {
            var origSliderStyle = $slider.data('bx-orig-style');
            if (origSliderStyle === null) {
                $slider.removeAttr('style');
            } else {
                $slider.attr('style', origSliderStyle);
            }

            $slides.each(function () {
                var $slide = $(this);
                var origStyle = $slide.data('bx-orig-style');
                if (origStyle === null) {
                    $slide.removeAttr('style');
                } else {
                    $slide.attr('style', origStyle);
                }
            });
        }

        var resizeNs = '.bxSliderLite-' + Math.random().toString(36).slice(2);
        if (settings.responsive) {
            $(window).on('resize' + resizeNs, handleResize);
        }

        applyLayout();
        settings.onSliderLoad(state.index);

        var api = {
            goToSlide: function (index, direction) {
                goToPage(parseInt(index, 10) || 0, true, direction);
            },
            goToNextSlide: function () {
                goToPage(state.index + 1, true, 'next');
            },
            goToPrevSlide: function () {
                goToPage(state.index - 1, true, 'prev');
            },
            getCurrentSlide: function () {
                return state.index;
            },
            getCurrentSlideElement: function () {
                return $slides.eq(state.index);
            },
            getSlideCount: function () {
                return $slides.length;
            },
            redrawSlider: function () {
                applyLayout();
            },
            destroySlider: function () {
                if (state.destroyed) {
                    return;
                }
                state.destroyed = true;
                $(window).off('resize' + resizeNs);
                restoreOriginalStyles();
                if ($viewport.length && $wrapper.length) {
                    $slider.unwrap();
                    $slider.unwrap();
                }
            },
            reloadSlider: function (newOptions) {
                if (newOptions) {
                    settings = $.extend({}, settings, newOptions);
                }
                api.destroySlider();
                return $slider.bxSlider(settings);
            },
            startAuto: function () {},
            stopAuto: function () {}
        };

        return api;
    };
}(jQuery));
